import SafeScreen from "@/components/SafeScreen";
import useCurrentUser from "@/hooks/useCurrentUser";
import { useApi } from "@/lib/api";
import { Offer, Order, Product } from "@/types";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { router } from "expo-router";
import { ActivityIndicator, Text, TouchableOpacity, View } from "react-native";

export default function VendorScreen() {
  const api = useApi();
  const queryClient = useQueryClient();
  const { data: user, isLoading: userLoading } = useCurrentUser();
  const canManage = user?.role === "vendor" || user?.role === "admin";
  const { data: products = [], isLoading: productsLoading } = useQuery({ queryKey: ["vendor-products"], enabled: canManage, queryFn: async () => (await api.get<Product[]>("/admin/products")).data });
  const { data: orders = [] } = useQuery({ queryKey: ["vendor-orders"], enabled: canManage, queryFn: async () => (await api.get<{ orders: Order[] }>("/admin/orders")).data.orders });
  const { data: offers = [], isLoading: offersLoading } = useQuery({ queryKey: ["vendor-offers"], enabled: canManage, queryFn: async () => (await api.get<{ offers: Offer[] }>("/admin/offers")).data.offers });
  const statusMutation = useMutation({ mutationFn: async ({ orderId, status }: { orderId: string; status: string }) => api.patch(`/admin/orders/${orderId}/status`, { status }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ["vendor-orders"] }) });
  const offerMutation = useMutation({ mutationFn: async ({ offerId, status }: { offerId: string; status: "accepted" | "rejected" }) => api.patch(`/admin/offers/${offerId}`, { status }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ["vendor-offers"] }) });

  if (userLoading) return <SafeScreen><View className="flex-1 items-center justify-center"><Text className="text-text-secondary">Loading vendor workspace...</Text></View></SafeScreen>;
  if (!canManage) return <SafeScreen><View className="flex-1 items-center justify-center px-6"><Text className="text-text-primary text-xl font-bold">Vendor access required</Text><Text className="text-text-secondary mt-2 text-center">Ask an administrator to enable vendor access for your account.</Text><TouchableOpacity className="mt-6 rounded-full bg-primary px-6 py-3" onPress={() => router.back()}><Text className="font-bold text-background">Go back</Text></TouchableOpacity></View></SafeScreen>;

  const pendingCount = offers.filter((offer) => offer.status === "pending").length;
  return <SafeScreen><View className="flex-1 px-6 pt-6"><Text className="text-text-primary text-3xl font-bold">Vendor workspace</Text><Text className="text-text-secondary mt-1">Manage your catalog, offers, and fulfillment</Text><View className="mt-6 flex-row gap-3"><View className="flex-1 rounded-2xl bg-surface p-5"><Text className="text-text-secondary">Products</Text><Text className="text-text-primary mt-1 text-3xl font-bold">{productsLoading ? "..." : products.length}</Text></View><View className="flex-1 rounded-2xl bg-surface p-5"><Text className="text-text-secondary">Orders</Text><Text className="text-text-primary mt-1 text-3xl font-bold">{orders.length}</Text></View></View><View className="mt-6 flex-1"><Text className="text-text-primary mb-3 text-lg font-bold">Price offers {pendingCount ? `(${pendingCount} new)` : ""}</Text>{offersLoading ? <ActivityIndicator color="#1DB954" /> : offers.length === 0 ? <Text className="text-text-secondary">Customer offers will appear here.</Text> : offers.map((offer) => <OfferCard key={offer._id} offer={offer} pending={offerMutation.isPending} onRespond={(status) => offerMutation.mutate({ offerId: offer._id, status })} />)}<Text className="text-text-primary mb-3 mt-6 text-lg font-bold">Catalog</Text>{products.map((product) => <View key={product._id} className="mb-3 rounded-2xl bg-surface p-4"><View className="flex-row justify-between"><Text className="text-text-primary flex-1 font-bold">{product.name}</Text><Text className="text-primary font-bold">${product.price.toFixed(2)}</Text></View><Text className="text-text-secondary mt-2 text-sm">{product.stock} in stock</Text></View>)}<Text className="text-text-primary mb-3 mt-5 text-lg font-bold">Orders</Text>{orders.map((order) => <View key={order._id} className="mb-3 rounded-2xl bg-surface p-4"><View className="flex-row justify-between"><Text className="text-text-primary font-bold">#{order._id.slice(-8).toUpperCase()}</Text><Text className="text-text-secondary">${order.totalPrice.toFixed(2)}</Text></View><Text className="text-text-secondary mt-2 text-sm">{order.orderItems.length} item(s)</Text><TouchableOpacity className="mt-3 self-start rounded-full bg-primary px-4 py-2" onPress={() => statusMutation.mutate({ orderId: order._id, status: order.status === "pending" ? "shipped" : "delivered" })} disabled={statusMutation.isPending || order.status === "delivered"}><Text className="font-bold text-background">{order.status === "pending" ? "Mark shipped" : order.status === "shipped" ? "Mark delivered" : "Delivered"}</Text></TouchableOpacity></View>)}</View></View></SafeScreen>;
}

function OfferCard({ offer, pending, onRespond }: { offer: Offer; pending: boolean; onRespond: (status: "accepted" | "rejected") => void }) {
  const customerName = typeof offer.customer === "string" ? "Customer" : offer.customer.name;
  return <View className="mb-3 rounded-2xl border border-primary/30 bg-surface p-4"><View className="flex-row justify-between"><Text className="text-text-primary flex-1 font-bold">{offer.product.name}</Text><Text className="font-bold capitalize text-orange-500">{offer.status}</Text></View><Text className="text-text-secondary mt-2">{customerName} offered ${offer.offeredPrice.toFixed(2)} x {offer.quantity}</Text>{offer.message ? <Text className="text-text-secondary mt-2">“{offer.message}”</Text> : null}{offer.status === "pending" ? <View className="mt-3 flex-row gap-2"><TouchableOpacity className="flex-1 rounded-xl bg-primary py-3" onPress={() => onRespond("accepted")} disabled={pending}><Text className="text-center font-bold text-background">Accept</Text></TouchableOpacity><TouchableOpacity className="flex-1 rounded-xl border border-red-500 py-3" onPress={() => onRespond("rejected")} disabled={pending}><Text className="text-center font-bold text-red-500">Reject</Text></TouchableOpacity></View> : null}</View>;
}
